/// <summary>
/// Extension of InventDim datasource on InventJournalCount form.
/// </summary>
[ExtensionOf(formDataSourceStr(InventJournalCount, InventDim))]
final class METInventJournalCountDimDS_Extension
{
}

Method.Source:
/// <summary>
/// Restrict InventDim records on the form by user restricted warehouses
/// </summary>
public void init()
{
    next init();

    QueryBuildDataSource inventDimDS = this.query().dataSourceTable(tableNum(InventDim));

    if (inventDimDS && METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole)))
    {
        QueryBuildDataSource warehouseListDS = inventDimDS.addDataSource(tableNum(METUserSecurityWarehouseList));
        warehouseListDS.joinMode(JoinMode::NoExistsJoin);
        warehouseListDS.relations(false);
        warehouseListDS.addLink(fieldNum(InventDim, InventLocationId), fieldNum(METUserSecurityWarehouseList, InventLocationId));
        warehouseListDS.addLink(fieldNum(InventDim, dataAreaId), fieldNum(METUserSecurityWarehouseList, Company));
        warehouseListDS.addRange(fieldNum(METUserSecurityWarehouseList, RestrictCountingJournal)).value(queryValue(NoYes::Yes));

        QueryBuildDataSource securityGroupListDS = warehouseListDS.addDataSource(tableNum(METUserSecurityGroupList));
        securityGroupListDS.joinMode(JoinMode::ExistsJoin);
        securityGroupListDS.relations(false);
        securityGroupListDS.addLink(fieldNum(METUserSecurityWarehouseList, UserSecurityGroupId), fieldNum(METUserSecurityGroupList, UserSecurityGroupId));
        securityGroupListDS.addRange(fieldNum(METUserSecurityGroupList, UserId)).value(queryValue(curUserId()));
    }
}
